/* AG CRM V100 — Exclusão de imóvel exclusiva do Administrador + marca d'água automática no centro */
(function(){
  const WATERMARK_SRC='data:image/png;base64,';
  let watermarkImagePromise=null;

  function isPropertyAdmin(){
    try{
      const p=window.EIFirebaseCRM?.getProfile?.();
      if(p) return p.active!==false && p.role==='Administrador';
      const s=JSON.parse(localStorage.getItem('nexoSessionV1')||'null');
      return s?.role==='Administrador';
    }catch(e){return false}
  }
  window.agIsPropertyAdmin=isPropertyAdmin;

  function loadWatermark(){
    if(watermarkImagePromise) return watermarkImagePromise;
    watermarkImagePromise=new Promise((resolve,reject)=>{
      const img=new Image();
      img.onload=()=>resolve(img);
      img.onerror=reject;
      img.src=WATERMARK_SRC;
    });
    return watermarkImagePromise;
  }

  function readPhoto(file){
    return new Promise((resolve,reject)=>{
      const reader=new FileReader();
      reader.onerror=reject;
      reader.onload=()=>{
        const img=new Image();
        img.onerror=reject;
        img.onload=()=>resolve(img);
        img.src=reader.result;
      };
      reader.readAsDataURL(file);
    });
  }

  /* Substitui o compressor original: redimensiona e grava a marca AG nos pixels da imagem. */
  compressPropertyImage=async function(file){
    const img=await readPhoto(file);
    let w=img.naturalWidth||img.width,h=img.naturalHeight||img.height;
    const max=1600;
    if(w>max||h>max){const r=Math.min(max/w,max/h);w=Math.max(1,Math.round(w*r));h=Math.max(1,Math.round(h*r))}
    const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;
    const ctx=canvas.getContext('2d',{alpha:false});
    ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';
    ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);

    try{
      const wm=await loadWatermark();
      const minSide=Math.min(w,h);
      const ratio=(wm.naturalHeight||wm.height)/(wm.naturalWidth||wm.width||1);
      const targetW=Math.max(220,Math.min(Math.round(w*.52),Math.round(minSide*.62),900));
      const targetH=Math.max(80,Math.round(targetW*ratio));
      const x=Math.round((w-targetW)/2);
      const y=Math.round((h-targetH)/2);
      ctx.save();
      ctx.globalAlpha=.09;
      ctx.drawImage(wm,x,y,targetW,targetH);
      ctx.restore();
    }catch(err){
      /* fallback textual caso a logo não possa ser decodificada */
      const fontSize=Math.max(22,Math.round(Math.min(w,h)*.055));
      ctx.save();
      ctx.globalAlpha=.12;
      ctx.textAlign='center';
      ctx.textBaseline='middle';
      ctx.font=`700 ${fontSize}px Arial, sans-serif`;
      ctx.fillStyle='#ffffff';
      ctx.fillText('AG IMOBILIÁRIA',Math.round(w/2),Math.round(h/2));
      ctx.restore();
    }
    return canvas.toDataURL('image/jpeg',.80);
  };
  window.compressPropertyImage=compressPropertyImage;

  const originalDeleteItem=deleteItem;
  deleteItem=function(type,id){
    if(type!=='property') return originalDeleteItem(type,id);
    if(!isPropertyAdmin()){toast('Somente o Administrador pode excluir imóveis.');return}
    const p=(db.properties||[]).find(x=>x.id===id);if(!p)return;
    if(!confirm(`Excluir definitivamente o imóvel "${p.title||p.id}" (${p.id})?\n\nEle também será removido do catálogo público. Esta ação não pode ser desfeita.`))return;
    db.properties=(db.properties||[]).filter(x=>x.id!==id);
    try{pushActivity('⌫','Imóvel excluído',`${p.id} · ${p.title||''}`)}catch(e){}
    try{closeModal()}catch(e){}
    try{saveDB();syncPublicCatalog()}catch(e){console.error(e);toast('Não foi possível concluir a exclusão.');return}
    toast('Imóvel excluído pelo Administrador.');
  };
  window.deleteItem=deleteItem;

  function applyAdminDeleteVisibility(){
    const admin=isPropertyAdmin();
    document.querySelectorAll('#propertyGrid button[onclick*="deleteItem(\'property\'"]').forEach(btn=>{btn.hidden=!admin;btn.style.display=admin?'':'none'});
    const actions=document.querySelector('#modal.property-detail-shell .pw-summary-actions');
    const workspace=document.querySelector('#modal.property-detail-shell .property-workspace');
    if(actions&&workspace){
      let btn=actions.querySelector('.ag-admin-delete-property');
      if(admin&&!btn){
        btn=document.createElement('button');btn.type='button';btn.className='btn danger ag-admin-delete-property';btn.textContent='Excluir imóvel';
        btn.onclick=()=>deleteItem('property',workspace.dataset.property);
        actions.appendChild(btn);
      }else if(btn) btn.hidden=!admin;
    }
  }

  const originalRenderProperties=renderProperties;
  renderProperties=function(){const r=originalRenderProperties.apply(this,arguments);applyAdminDeleteVisibility();return r};
  window.renderProperties=renderProperties;

  const originalOpenPropertyDetails=openPropertyDetails;
  openPropertyDetails=function(){const r=originalOpenPropertyDetails.apply(this,arguments);setTimeout(()=>{applyAdminDeleteVisibility();addGalleryWatermarkNote()},0);return r};
  window.openPropertyDetails=openPropertyDetails;

  function addGalleryWatermarkNote(){
    const bar=document.querySelector('#modal.property-detail-shell .pw-gallery-toolbar');
    if(!bar||bar.querySelector('.ag-watermark-note'))return;
    const note=document.createElement('div');note.className='ag-watermark-note';note.innerHTML='<b>Marca d’água automática</b><span>Toda nova foto recebe a marca d’água AG em baixa opacidade no centro antes de ser salva.</span>';
    bar.appendChild(note);
  }

  document.addEventListener('DOMContentLoaded',()=>{
    applyAdminDeleteVisibility();
    const role=document.getElementById('cloudRole');
    if(role) new MutationObserver(()=>applyAdminDeleteVisibility()).observe(role,{childList:true,subtree:true,characterData:true});
  });
})();
